draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2*Math.PI);
  ctx.stroke();
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 40*Math.sin(2*Math.PI*t), H/2 + 40*Math.cos(2*Math.PI*t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 20*Math.sin(4*Math.PI*t), H/2 + 20*Math.cos(4*Math.PI*t));
  ctx.stroke();
  ctx.restore();
}
